/** `<WrapBox>`: an AdwWrapBox. */
export class AdwWrapBoxNode extends WidgetNode {
  readonly gtk: AdwWrapBox;

  constructor() {
    const gtk = new AdwWrapBox();
    super("AdwWrapBox", gtk);
    this.gtk = gtk;
  }
  setProp(key: string, value: unknown): boolean {
    return wrapBoxProp(this.gtk, key, value);
  }
  connectSignal(key: string, slot: SignalSlot): boolean {
    return wrapBoxSignal(this.gtk, key, slot);
  }
  protected place(child: WidgetNode, moving: boolean): void {
    // A child already here is a move to the end: React appends it again.
    if (!moving) {
      this.gtk.append(child.widget);
      return;
    }
    const last = this.gtk.get_last_child();
    if (last !== child.widget) {
      this.gtk.reorder_child_after(child.widget, last);
    }
  }
  protected placeBefore(child: WidgetNode, before: WidgetNode, moving: boolean): void {
    // GTK places a child after a sibling; React places it before one. A
    // child already here is a move -- a keyed list reordered.
    const after = before.widget.get_prev_sibling();
    if (moving) {
      if (after !== child.widget) {
        this.gtk.reorder_child_after(child.widget, after);
      }
    } else {
      this.gtk.insert_child_after(child.widget, after);
    }
  }
  protected unplace(child: WidgetNode): void {
    this.gtk.remove(child.widget);
  }
}

/**
 * A new node for the host type `type` (`GtkButton`, or a slot element's
 * `GtkPaned.StartChild`), or null when there is no such element.
 */
export function createNode(type: string): HostNode | null {
  switch (type) {
    case "AdwAboutDialog":
      return new AdwAboutDialogNode();
    case "AdwActionRow":
      return new AdwActionRowNode();
    case "AdwAlertDialog":
      return new AdwAlertDialogNode();
    case "AdwApplicationWindow":
      return new AdwApplicationWindowNode();
    case "AdwAvatar":
      return new AdwAvatarNode();
    case "AdwBanner":
      return new AdwBannerNode();
    case "AdwBin":
      return new AdwBinNode();
    case "AdwBottomSheet":
      return new AdwBottomSheetNode();
    case "AdwBreakpointBin":
      return new AdwBreakpointBinNode();
    case "AdwButtonContent":
      return new AdwButtonContentNode();
    case "AdwButtonRow":
      return new AdwButtonRowNode();
    case "AdwCarousel":
      return new AdwCarouselNode();
    case "AdwCarouselIndicatorDots":
      return new AdwCarouselIndicatorDotsNode();
    case "AdwCarouselIndicatorLines":
      return new AdwCarouselIndicatorLinesNode();
    case "AdwClamp":
      return new AdwClampNode();
    case "AdwClampScrollable":
      return new AdwClampScrollableNode();
    case "AdwComboRow":
      return new AdwComboRowNode();
    case "AdwDialog":
      return new AdwDialogNode();
    case "AdwEntryRow":
      return new AdwEntryRowNode();
    case "AdwExpanderRow":
      return new AdwExpanderRowNode();
    case "AdwHeaderBar":
      return new AdwHeaderBarNode();
    case "AdwInlineViewSwitcher":
      return new AdwInlineViewSwitcherNode();
    case "AdwMultiLayoutView":
      return new AdwMultiLayoutViewNode();
    case "AdwNavigationPage":
      return new AdwNavigationPageNode();
    case "AdwNavigationSplitView":
      return new AdwNavigationSplitViewNode();
    case "AdwNavigationView":
      return new AdwNavigationViewNode();
    case "AdwOverlaySplitView":
      return new AdwOverlaySplitViewNode();
    case "AdwPasswordEntryRow":
      return new AdwPasswordEntryRowNode();
    case "AdwPreferencesDialog":
      return new AdwPreferencesDialogNode();
    case "AdwPreferencesGroup":
      return new AdwPreferencesGroupNode();
    case "AdwPreferencesPage":
      return new AdwPreferencesPageNode();
    case "AdwPreferencesRow":
      return new AdwPreferencesRowNode();
    case "AdwShortcutLabel":
      return new AdwShortcutLabelNode();
    case "AdwShortcutsDialog":
      return new AdwShortcutsDialogNode();
    case "AdwSidebar":
      return new AdwSidebarNode();
    case "AdwSpinner":
      return new AdwSpinnerNode();
    case "AdwSpinRow":
      return new AdwSpinRowNode();
    case "AdwSplitButton":
      return new AdwSplitButtonNode();
    case "AdwStatusPage":
      return new AdwStatusPageNode();
    case "AdwSwitchRow":
      return new AdwSwitchRowNode();
    case "AdwTabBar":
      return new AdwTabBarNode();
    case "AdwTabButton":
      return new AdwTabButtonNode();
    case "AdwTabOverview":
      return new AdwTabOverviewNode();
    case "AdwTabView":
      return new AdwTabViewNode();
    case "AdwToastOverlay":
      return new AdwToastOverlayNode();
    case "AdwToggleGroup":
      return new AdwToggleGroupNode();
    case "AdwToolbarView":
      return new AdwToolbarViewNode();
    case "AdwViewStack":
      return new AdwViewStackNode();
    case "AdwViewSwitcher":
      return new AdwViewSwitcherNode();
    case "AdwViewSwitcherBar":
      return new AdwViewSwitcherBarNode();
    case "AdwViewSwitcherSidebar":
      return new AdwViewSwitcherSidebarNode();
    case "AdwWindow":
      return new AdwWindowNode();
    case "AdwWindowTitle":
      return new AdwWindowTitleNode();
    case "AdwWrapBox":
      return new AdwWrapBoxNode();
    case "AdwWindow.Content":
    case "AdwActionRow.ActivatableWidget":
    case "AdwAlertDialog.ExtraChild":
    case "AdwApplicationWindow.Content":
    case "AdwBottomSheet.BottomBar":
    case "AdwBottomSheet.Content":
    case "AdwBottomSheet.Sheet":
    case "AdwHeaderBar.TitleWidget":
    case "AdwNavigationSplitView.Content":
    case "AdwNavigationSplitView.Sidebar":
    case "AdwOverlaySplitView.Content":
    case "AdwOverlaySplitView.Sidebar":
    case "AdwPreferencesGroup.HeaderSuffix":
    case "AdwPreferencesPage.Banner":
    case "AdwSidebar.Placeholder":
    case "AdwTabBar.EndActionWidget":
    case "AdwTabBar.StartActionWidget":
    case "AdwToolbarView.Content":
    case "AdwViewSwitcherSidebar.Placeholder":
      return new SlotNode(type);
    case "AdwHeaderBar.Start":
      return new AdwGroupNode(type);
    case "AdwHeaderBar.End":
      return new AdwGroupNode(type);
    case "AdwToolbarView.Top":
      return new AdwGroupNode(type);
    case "AdwToolbarView.Bottom":
      return new AdwGroupNode(type);
    case "AdwActionRow.Prefix":
      return new AdwGroupNode(type);
    case "AdwActionRow.Suffix":
      return new AdwGroupNode(type);
    case "AdwEntryRow.Prefix":
      return new AdwGroupNode(type);
    case "AdwEntryRow.Suffix":
      return new AdwGroupNode(type);
    case "AdwExpanderRow.Prefix":
      return new AdwGroupNode(type);
    case "AdwExpanderRow.Suffix":
      return new AdwGroupNode(type);
    case "AdwViewStack.Page":
      return new ViewStackPageNode(type);
    case "AdwTabView.Page":
      return new TabViewPageNode(type);
    case "AdwWindow.Breakpoint":
      return new BreakpointNode(type);
    case "AdwApplicationWindow.Breakpoint":
      return new BreakpointNode(type);
    case "AdwBreakpointBin.Breakpoint":
      return new BreakpointNode(type);
    case "AdwToastOverlay.Toast":
      return new ToastNode(type);
    case "AdwSidebar.Section":
      return new SidebarSectionNode(type);
    case "AdwSidebar.Item":
      return new SidebarItemNode(type);
    case "AdwToggleGroup.Toggle":
      return new ToggleNode(type);
    case "AdwAlertDialog.Response":
      return new AlertResponseNode(type);
    case "AdwDialog.Breakpoint":
      return new BreakpointNode(type);
  }
  return null;
}
